{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.5",
  "body": [
    {
      "type": "TextBlock",
      "size": "Large",
      "weight": "Bolder",
      "id": "Title",
      "text": "@{triggerBody()?['text_3']} transition approved based on majority voting for project @{triggerBody()?['text_2']}",
      "horizontalAlignment": "Left",
      "isSubtle": false,
      "wrap": true
    },
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
     {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Completed By",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Response",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Completed On",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Comments",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
    @{join(variables('arrAdaptiveCardApprovalResponseRows'),',')},
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Project details:",
      "weight": "Bolder",
      "size": "Large",
      "horizontalAlignment": "Left",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Name",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Value",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
    @{triggerBody()['text_16']},
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Check List:",
      "weight": "Bolder",
      "size": "Large",
      "spacing": "Medium",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "State",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        },{
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Description",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        }
      ]
    },
    @{triggerBody()?['text_12']}
  ]
}

